import{C as e,L as t,S as n,V as r,_ as i,b as a,x as o}from"./vue-Vea_iehr.js";import{oi as s}from"./common-DL9_79Qg.js";var c=JSON.parse(`{"path":"/os/debian/64i2k4fj/","title":"在 Debian 12 中修改 IP 地址 | Debian","lang":"zh-CN","frontmatter":{"title":"在 Debian 12 中修改 IP 地址","createTime":"2026/08/25 16:39:25","permalink":"/os/debian/64i2k4fj/"},"readingTime":{"minutes":1.83,"words":550},"git":{},"filePathRelative":"os/debian/Standard 镜像/001.changing-ip-address-in-debian-12.md","headers":[]}`),l={name:`001.changing-ip-address-in-debian-12.md`},u={class:`code-block-title`,"data-title":`/etc/resolv.conf`},d={class:`code-block-title-bar`},f={class:`title`};function p(s,c,l,p,m,h){let g=r(`VPIcon`);return t(),a(`div`,null,[c[6]||=o(`<blockquote><p>新安装的 Debian 系统，默认一般使用 DHCP 获取 IP 地址，除非在安装过程中，使用了指定的 IP 地址。本文将介绍如何在 Debian 系统中，配置使用静态 IP 地址，配置网关，以及设置 DNS 服务器。</p></blockquote><p>这些配置通过修改配置文件，很容易实现。在 Redhat 系列的 Linux 环境中，我们一般修改网卡的网络配置文件，对应的文件名为 <code class="fp">/etc/sysconfig/network-scripts/ifcfg-eXX</code>，其中 <kbd>eXX</kbd> 即为网络设备名。网络设备的列表可以他通过 <code>ifconfig</code> 命令获取。同样的，在 Debian 环境下，我们只需要修改网络的配置文件便可以了。相比之下，配置过程要比 Redhat 更为方便，只需要修改 <code class="fp">/etc/network/interfaces</code> 文件。</p><div class="hint-container important"><p class="hint-container-title">以 <code>root</code> 权限打开 <code>/etc/network/interfaces</code></p></div><h2 id="debian-系统设置静态-ip-地址、网关" tabindex="-1"><a class="header-anchor" href="#debian-系统设置静态-ip-地址、网关"><span>Debian 系统设置静态 IP 地址、网关</span></a></h2><p>首选备份原始的网络配置文件</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/network/interfaces</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  /etc/network/interfacesbak</span></span></code></pre></div><p>编辑文件 <code class="fp">/etc/network/interfaces</code>，内容如下：</p><div class="code-block-title" data-title="/etc/network/interfaces"><div class="code-block-title-bar"><span class="title">/etc/network/interfaces</span></div><div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The loopback network interface</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auto lo</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auto eth0  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#设置开机自动连接网络</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">iface lo inet loopback</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The primary network interface</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">allow-hotplug eth0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">iface eth0 inet static   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#static表示使用固定IP地址上网，dhcp表示使用动态ip</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">address 192.168.9.100    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#设置静态ip地址</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">netmask 255.255.255.0    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#子网掩码</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gateway 192.168.9.254    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#网关</span></span></code></pre></div></div><p>使用 <kbd>Ctrl + O</kbd> 保存配置，使用 <kbd>Ctrl + X</kbd> 退出 <strong>nano</strong> 编辑器。</p><h2 id="配置-debian-环境中的-dns-服务器" tabindex="-1"><a class="header-anchor" href="#配置-debian-环境中的-dns-服务器"><span>配置 Debian 环境中的 DNS 服务器</span></a></h2>`,10),i(`p`,null,[c[0]||=n(`这个配置过程与 `,-1),e(g,{provider:`iconify`,size:`24px`,name:`devicon:redhat-wordmark`}),c[1]||=n(` 系列的系统是相同的，只需要修改 `,-1),c[2]||=i(`code`,{class:`fp`},`/etc/resolv.conf`,-1),c[3]||=n(` 文件即可，内容如下，`,-1)]),i(`div`,u,[i(`div`,d,[i(`span`,f,[e(g,{provider:`iconify`,name:`vscode-icons:file-type-config`}),c[4]||=n(`/etc/resolv.conf`,-1)])]),c[5]||=o(`<div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nameserver 114.114.114.114   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#设置首选dns</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nameserver 8.8.8.8   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#设置备用dns</span></span></code></pre></div>`,1)]),c[7]||=o(`<p>至此，IP地址、网关、DNS配置完成。</p><p>重启网络使配置生效：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> networking</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span></span></code></pre></div><p>检查新配置是否工作：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> www.debian.cn</span></span></code></pre></div><div class="hint-container warning"><p class="hint-container-title">如果重启网络后，配置并没有生效</p><ol><li>请检查是否有书写错误，比如全角和半角字符；</li><li><code class="fp">interfaces</code> 文件中 <code>auto eth0</code> 也很关键， <code class="fp">/etc/init.d/networking</code> 根据这个字段判断是否启动某个网卡的网络；</li></ol></div><h2 id="参考" tabindex="-1"><a class="header-anchor" href="#参考"><span>参考</span></a></h2><p><a href="https://www.cnblogs.com/Thenext/p/16950850.html" target="_blank" rel="noopener noreferrer">debian 11修改ip地址的方法 - Thenext - 博客园</a></p>`,8)])}var m=s(l,[[`render`,p]]);export{c as _pageData,m as default};